// Generates docs/RULES.md from the rule registry. `--check` fails if the file is out of date.
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { rules } from '../src/rules/index.js';

const target = new URL('../docs/RULES.md', import.meta.url);

function cell(s: string): string {
  return s.replace(/\|/g, '\\|').replace(/\n/g, ' ');
}

export function renderRulesDoc(): string {
  const sorted = [...rules].sort((a, b) => a.id.localeCompare(b.id));
  const lines: string[] = [
    '# Rule catalog',
    '',
    '<!-- Generated by `npm run docs:gen`. Do not edit by hand. -->',
    '',
    `${sorted.length} rules. "Verified on" is the date the message format was checked against real tool output; "not verified" means the format comes from documentation or knowledge of the tool and has not been checked against a real run, so treat matches with extra care.`,
    '',
    'Fixtures for every rule are synthetic and written by hand; passing them does not measure accuracy on real logs.',
    '',
    '| Rule id | Title | Ecosystem | Category | Kind | Default confidence | Verified on |',
    '| --- | --- | --- | --- | --- | --- | --- |',
  ];
  for (const r of sorted) {
    lines.push(
      `| \`${r.id}\` | ${cell(r.title)} | ${r.ecosystem} | ${r.category} | ${r.kind} | ${r.confidence} | ${r.verifiedOn ?? 'not verified'} |`,
    );
  }
  lines.push('', '## Source notes', '');
  for (const r of sorted) {
    lines.push(`### \`${r.id}\``, '', r.sourceNote, '');
  }
  return lines.join('\n');
}

const text = renderRulesDoc();
if (process.argv.includes('--check')) {
  const current = existsSync(target) ? readFileSync(target, 'utf8') : '';
  if (current !== text) {
    console.error('docs/RULES.md is out of date. Run `npm run docs:gen` and commit the result.');
    process.exit(1);
  }
  console.log('docs/RULES.md is in sync with the rule registry.');
} else {
  writeFileSync(target, text);
  console.log('Wrote docs/RULES.md');
}
